#' Show the tissue
#'
#' Shows a dataset in the Viewer as asked, everything else as the Viewer shows it now: where (a
#' center in µm and µm per screen pixel, or a width in µm; the whole section with whole: true),
#' the stains (by name: visible, color, brightness window, gamma), the transcripts of genes by
#' name (up to 16) or all of them, their minimum quality and point size, which of the dataset's
#' segmentations is drawn, the cell and nucleus outlines, a cell fill and its opacity, a graph
#' of the cells, a spatial analysis's cells, the transcripts colored by gene or by their
#' assignment's probability, and a cell to select. Returns what it shows, as a saved view
#' records it, and what the dataset lacks.
#'
#' @param all_transcripts Show every transcript, in one color. Optional; TRUE or FALSE (Python:
#' True or False).
#' @param cell A cell to select, by its ID in the segmentation drawn (as cells.parquet names
#' the instrument's). Optional; a string.
#' @param cells_of A spatial analysis's cells: {analysis (its ID, or latest), a, b (labels by
#' name), distance (a co-occurrence's, a nearest distance's or a Ripley radius, µm)}: an
#' enrichment's pair, their cells neighboring each other and the edges between them; or label
#' b's cells within the distance of a's. Regions compared: {analysis, a, region (a region's
#' name, or the row of the tissue in none)}: label a's cells in it. Across an edge: {analysis,
#' a (any label if not given), zone (core, margin, around or all)}: label a's cells there.
#' Niches: {analysis, niche (its number from 1)}: the niche's cells, filled by niche. Moran's
#' I: {analysis, gene (one whose local Moran's I was kept), class (high, low, high-low,
#' low-high or all)}: the gene's cells of that local class. The cells filled by the analysis's
#' labels. Optional; a named list (Python: a dict).
#' @param center The center, [x, y] in µm. Optional; a vector of numbers (Python: a list).
#' @param channels By stain name (DAPI, ATP1A1/CD45/E-Cadherin, 18S, alphaSMA/Vimentin…):
#' {visible, color (#rrggbb), window: [low, high], gamma}, each optional. Optional; a named
#' list (Python: a dict).
#' @param color_by Color the transcripts by gene (as listed) or probability (their
#' assignment's, a refinement's; seen close up). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param fill Fill the cells by transcripts, total, area, nucleusArea or method (the
#' instrument's); limitations, certainty or probability (a refinement's); clusters (the latest
#' clustering of the segmentation drawn) or clusters:<artifact id>; labels (the latest label
#' set, its first level), labels:<level> or labels:<artifact id>:<level>; review (each cell by
#' its review: excluded, a segmentation concern, ambiguous, relabeled, accepted or commented);
#' none for no fill. Optional; a string.
#' @param genes Genes whose transcripts are shown, by name (each in its color); [] for none.
#' Optional; a vector of strings (Python: a list).
#' @param graph A graph of the segmentation drawn, its edges drawn over the cells when zoomed
#' in: by artifact ID, latest for the last built, none for none. Optional; a string.
#' @param images Post-Xenium images, by name or artifact ID: {visible, opacity (0 to 1),
#' channels: {by name: {visible, color, window, gamma}} (immunofluorescence)}, each optional.
#' Optional; a named list (Python: a dict).
#' @param min_quality The lowest quality (qv) shown: 20 (the default) or 0 for all. Optional; a
#' number.
#' @param nuclei Draw the nucleus outlines. Optional; TRUE or FALSE (Python: True or False).
#' @param opacity The fill's opacity, 0 to 1. Optional; a number.
#' @param outlines Draw the cell outlines. Optional; TRUE or FALSE (Python: True or False).
#' @param picture Answer a picture of what the Viewer shows too, drawn as a figure's tissue
#' panel draws it, with its scale bar and legend (a JPEG): an agent gets it as an image.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param picture_width The picture's width in pixels (1,000; 300 to 2,000). Optional; a
#' number.
#' @param point_size The transcripts' point size, 1 to 8 pixels. Optional; a number.
#' @param segmentation The segmentation drawn: by its name or artifact ID, instrument for the
#' instrument's, default for the dataset's default. Optional; a string.
#' @param transcripts Show transcripts at all (false hides them). Optional; TRUE or FALSE
#' (Python: True or False).
#' @param um_per_pixel The zoom: µm per screen (CSS) pixel. Optional; a number.
#' @param whole Show the whole section. Optional; TRUE or FALSE (Python: True or False).
#' @param width_um The zoom as the width of tissue shown, in µm. Optional; a number.
#' @param file Optional; ask for the picture and save it to this path (the tissue a JPEG, a map or a figure a PNG).
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_show_tissue <- function(all_transcripts = NULL, cell = NULL, cells_of = NULL, center = NULL, channels = NULL, color_by = NULL, dataset = NULL, fill = NULL, genes = NULL, graph = NULL, images = NULL, min_quality = NULL, nuclei = NULL, opacity = NULL, outlines = NULL, picture = NULL, picture_width = NULL, point_size = NULL, segmentation = NULL, transcripts = NULL, um_per_pixel = NULL, whole = NULL, width_um = NULL, file = NULL, sc = sc_default()) {
  if (!is.null(file) && is.null(picture)) picture <- TRUE
  result <- sc_call("show_tissue", all_transcripts = all_transcripts, cell = cell, cells_of = cells_of, center = .sc_array(center), channels = channels, color_by = color_by, dataset = dataset, fill = fill, genes = .sc_array(genes), graph = graph, images = images, min_quality = min_quality, nuclei = nuclei, opacity = opacity, outlines = outlines, picture = picture, picture_width = picture_width, point_size = point_size, segmentation = segmentation, transcripts = transcripts, um_per_pixel = um_per_pixel, whole = whole, width_um = width_um, sc = sc)
  if (!is.null(file)) sc_save_image(result, file)
  result
}

#' Add a post-Xenium image
#'
#' Adds an H&E or immunofluorescence image of a dataset's section, stained and scanned after
#' the Xenium run, as a job: a pyramidal, tiled OME-TIFF (as Xenium Explorer requires; RGB, or
#' channels of 8 or 16 bits; deflate, LZW, JPEG or JPEG 2000), read where it lies, never
#' copied, and recorded as an image artifact with its SHA-256. Its alignment, the
#' transformation matrix or keypoints Xenium Explorer saves (found beside the image when 10x
#' named it, else named; null for none), is recorded as the image's first transform and places
#' it; without one the image is not aligned until align_image places it. The Viewer draws an
#' aligned image under the transcripts and cells. Needs the token (it reads files). Answers
#' what the image is and how it is placed.
#'
#' @param path The image: an OME-TIFF on this computer. Required; a string.
#' @param alignment Its alignment: <name>_imagealignment.csv (the transformation matrix) or
#' <name>_keypoints.csv (found beside the image if not given; null to add it unaligned).
#' Optional; any value.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param name What to call it (from its file's name if not given). Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_add_image <- function(path, alignment = NULL, dataset = NULL, name = NULL, sc = sc_default()) {
  sc_call("add_image", path = path, alignment = alignment, dataset = dataset, name = name, sc = sc)
}

#' Align an image by landmarks
#'
#' Fits a post-Xenium image's alignment to landmarks, each a point placed on both images, and
#' records it as a version of the image's alignment (a transform artifact: its landmarks, the
#' fit, each landmark's residual and leave-one-out error in µm, who made it, a note and the
#' version it was made from). A similarity (move, turn, one scale and a mirror when that fits
#' better; Umeyama 1991) or an affine transform (also stretched and sheared), by least squares,
#' from three landmarks or more. With use (the default), the version places the image. Answers
#' the fit.
#'
#' @param landmarks Each landmark: {"fixed": [x, y] on the tissue (µm, Xenium's coordinates),
#' "moving": [x, y] on the image (its full-resolution pixels, (0, 0) the corner of its first)}.
#' Required; a list of named lists (Python: a list of dicts).
#' @param by Who placed the landmarks (the client's name if not given). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param image The image, by name or artifact ID (the dataset's only image if not given).
#' Optional; a string.
#' @param model similarity (the default) or affine. Optional; a string.
#' @param note A note kept with the version (and the reason, when it is used). Optional; a
#' string.
#' @param parent The version it is made from, by name or ID. Optional; a string.
#' @param use Place the image by it (the default true). Optional; TRUE or FALSE (Python: True
#' or False).
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_align_image <- function(landmarks, by = NULL, dataset = NULL, image = NULL, model = NULL, note = NULL, parent = NULL, use = NULL, sc = sc_default()) {
  sc_call("align_image", landmarks = .sc_array(landmarks), by = by, dataset = dataset, image = image, model = model, note = note, parent = parent, use = use, sc = sc)
}

#' Align an image automatically
#'
#' Aligns a post-Xenium image to its dataset's Xenium image automatically, by the nuclei (an
#' H&E's hematoxylin by color deconvolution, an immunofluorescence image's nuclear stain,
#' against DAPI), as a job: its scale, turn and mirroring found whatever its metadata says
#' (phase correlation and its log-polar form), refined by normalized mutual information, then
#' fitted to local matches over the tissue; optionally a smooth deformation after it
#' (B-splines), kept only when it predicts the matches better. Recorded as a version of the
#' image's alignment with its matches, fit and what the search found; with use (the default),
#' it places the image. The same images give the same version on any computer. Answers the fit.
#'
#' @param by Who asked for it (the client's name if not given). Optional; a string.
#' @param channel An immunofluorescence image's nuclear stain, by name (the channel named as
#' one, DAPI or Hoechst, if not given). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param image The image, by name or artifact ID (the dataset's only image if not given).
#' Optional; a string.
#' @param model similarity (the default) or affine. Optional; a string.
#' @param nonrigid Allow a smooth deformation after the model, for a section that stretched.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param note A note kept with the version (and the reason, when it is used). Optional; a
#' string.
#' @param start A version to start from instead of searching, by name or ID ('in use' for the
#' one placing the image). Optional; a string.
#' @param use Place the image by it (the default true). Optional; TRUE or FALSE (Python: True
#' or False).
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_register_image <- function(by = NULL, channel = NULL, dataset = NULL, image = NULL, model = NULL, nonrigid = NULL, note = NULL, start = NULL, use = NULL, sc = sc_default()) {
  sc_call("register_image", by = by, channel = channel, dataset = dataset, image = image, model = model, nonrigid = nonrigid, note = note, start = start, use = use, sc = sc)
}

#' Place an image by a version of its alignment
#'
#' Chooses which version of a post-Xenium image's alignment places it, as a decision recorded
#' with its reason, who and when.
#'
#' @param transform The version, by name or artifact ID. Required; a string.
#' @param by Who chooses it (the client's name if not given). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param image The image, by name or artifact ID (the dataset's only image if not given).
#' Optional; a string.
#' @param rationale Why it is chosen. Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_use_transform <- function(transform, by = NULL, dataset = NULL, image = NULL, rationale = NULL, sc = sc_default()) {
  sc_call("use_transform", transform = transform, by = by, dataset = dataset, image = image, rationale = rationale, sc = sc)
}

