sc_show_alignment <- function(cell = NULL, dataset = NULL, display = NULL, edges = NULL, image = NULL, map = NULL, opacity = NULL, outlines = NULL, show = NULL, transform = NULL, sc = sc_default()) {
  sc_call("show_alignment", cell = cell, dataset = dataset, display = display, edges = edges, image = image, map = map, opacity = opacity, outlines = outlines, show = show, transform = transform, sc = sc)
