#' Expand the nuclei
#'
#' SituCraft's nucleus expansion of a dataset: each nucleus of the instrument's segmentation
#' grows by up to distance_um (5 if not given), every pixel going to the nearest nucleus within
#' it, and transcripts to the cell holding their pixel. Runs as a job (seconds) in the
#' Segmentation view, which shows it; the result is a segmentation artifact recorded in the
#' project, compared with the instrument's segmentation. Answers its summary and that
#' comparison.
#'
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param distance_um How far each nucleus grows, in µm (5 if not given). Optional; a number.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_expand_nuclei <- function(dataset = NULL, distance_um = NULL, sc = sc_default()) {
  sc_call("expand_nuclei", dataset = dataset, distance_um = distance_um, sc = sc)
}

#' Refine the segmentation from the transcripts
#'
#' SituCraft's transcript-informed segmentation of a dataset (after Jones et al. 2025), in the
#' Segmentation view's studio: starting from the instrument's cells and their nuclei, each
#' cell's boundary moves to where its own transcripts are, sampled from the posterior; the
#' result is its summary over the last sweeps, with each transcript's probability of its cell.
#' A preset sets the model (balanced if not given); regions or sections limit what it covers,
#' the rest keeping the instrument's cells. Runs as a job (minutes per square millimetre); its
#' failures are classified with what to do. The segmentation artifact is recorded in the
#' project and compared with the instrument's segmentation. Answers its summary, diagnostics
#' and that comparison.
#'
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param layers Voxel layers in depth (1 if not given). Optional; a whole number.
#' @param min_qv The quality the modeled transcripts reach (20 if not given). Optional; a
#' number.
#' @param preset The settings' preset: balanced (the default), conservative, flexible,
#' low-memory, roi-pilot (a region, run with two seeds) or expert. Optional; a string.
#' @param regions Regions to refine, each [x0, y0, x1, y1] in µm; the rest of the tissue keeps
#' the instrument's cells. Optional; a list of vectors (Python: a list of lists).
#' @param samples The last sweeps summarized (the preset's if not given, at most the sweeps).
#' Optional; a whole number.
#' @param sections Refine the tissue's separate sections apart, each with a model of its own.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param seed The random seed (20250 if not given); a seed gives the same segmentation on any
#' computer. Optional; a whole number.
#' @param seed_check Run again with the next seed and report how many transcripts both runs put
#' in the same cell. Optional; TRUE or FALSE (Python: True or False).
#' @param sweeps Sweeps of the sampler (the preset's if not given; changing it makes the
#' settings expert). Optional; a whole number.
#' @param threads Threads to run on (every core if not given); the result does not depend on
#' them. Optional; a whole number.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_refine_segmentation <- function(dataset = NULL, layers = NULL, min_qv = NULL, preset = NULL, regions = NULL, samples = NULL, sections = NULL, seed = NULL, seed_check = NULL, sweeps = NULL, threads = NULL, sc = sc_default()) {
  sc_call("refine_segmentation", dataset = dataset, layers = layers, min_qv = min_qv, preset = preset, regions = .sc_array(regions), samples = samples, sections = sections, seed = seed, seed_check = seed_check, sweeps = sweeps, threads = threads, sc = sc)
}

#' Check a refinement before it runs
#'
#' What a transcript-informed segmentation of a dataset would model, cover and cost, without
#' running it: the transcripts at the quality, the cells it starts from, the regions or
#' sections, its memory, disk and time against what the computer has, its problems (which stop
#' it) and risks, and its recipe (JSON, to keep or run with `situcraft refine --recipe`). Takes
#' the same arguments as refine_segmentation.
#'
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param layers Voxel layers in depth (1 if not given). Optional; a whole number.
#' @param min_qv The quality the modeled transcripts reach (20 if not given). Optional; a
#' number.
#' @param preset The settings' preset: balanced (the default), conservative, flexible,
#' low-memory, roi-pilot (a region, run with two seeds) or expert. Optional; a string.
#' @param regions Regions to refine, each [x0, y0, x1, y1] in µm; the rest of the tissue keeps
#' the instrument's cells. Optional; a list of vectors (Python: a list of lists).
#' @param samples The last sweeps summarized (the preset's if not given, at most the sweeps).
#' Optional; a whole number.
#' @param sections Refine the tissue's separate sections apart, each with a model of its own.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param seed The random seed (20250 if not given); a seed gives the same segmentation on any
#' computer. Optional; a whole number.
#' @param seed_check Run again with the next seed and report how many transcripts both runs put
#' in the same cell. Optional; TRUE or FALSE (Python: True or False).
#' @param sweeps Sweeps of the sampler (the preset's if not given; changing it makes the
#' settings expert). Optional; a whole number.
#' @param threads Threads to run on (every core if not given); the result does not depend on
#' them. Optional; a whole number.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_refinement_preflight <- function(dataset = NULL, layers = NULL, min_qv = NULL, preset = NULL, regions = NULL, samples = NULL, sections = NULL, seed = NULL, seed_check = NULL, sweeps = NULL, threads = NULL, sc = sc_default()) {
  sc_call("refinement_preflight", dataset = dataset, layers = layers, min_qv = min_qv, preset = preset, regions = .sc_array(regions), samples = samples, sections = sections, seed = seed, seed_check = seed_check, sweeps = sweeps, threads = threads, sc = sc)
}

#' Import a segmentation
#'
#' Imports another tool's segmentation into a dataset, in the Segmentation view, which shows
#' it: a SpatialData Zarr store (spatialdata), Baysor's segmentation.csv with its polygons
#' (baysor), GeoJSON polygons with an optional transcript table (geojson), a Xenium Ranger
#' output bundle of the same run (xenium), or a folder of SituCraft's own segmentation files,
#' as `situcraft refine` writes them (situcraft). A job reads it, checks it against the dataset
#' (the transcripts it names, where its cells lie, its ids) and records it as a segmentation
#' artifact with the files' SHA-256; an import whose check finds a fatal problem is recorded as
#' invalid. Coordinates are read in units (um, else pixels of the morphology image), never
#' guessed. Needs the token (it reads files).
#'
#' @param format spatialdata, baysor, geojson, xenium or situcraft. Required; a string.
#' @param paths The files: a store or bundle; or Baysor's segmentation.csv and its polygons; or
#' GeoJSON polygons and a transcript table (CSV or Parquet); or the folder situcraft refine
#' wrote. Required; a vector of strings (Python: a list).
#' @param cell_column The assignment's cell column (chosen from the usual names if not given).
#' Optional; a string.
#' @param cell_property GeoJSON: the property naming each polygon's cell. Optional; a string.
#' @param cells SpatialData: the shapes or labels element holding the cells. Optional; a
#' string.
#' @param citation The paper to cite for it. Optional; a string.
#' @param coordinate_system SpatialData: the coordinate system (global). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param points SpatialData: the points element with each transcript's cell. Optional; a
#' string.
#' @param table SpatialData: the table annotating the cells. Optional; a string.
#' @param tool What made it (recorded with it). Optional; a string.
#' @param tool_version Its version. Optional; a string.
#' @param units um (the default) or pixels (of the morphology image). Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_import_segmentation <- function(format, paths, cell_column = NULL, cell_property = NULL, cells = NULL, citation = NULL, coordinate_system = NULL, dataset = NULL, points = NULL, table = NULL, tool = NULL, tool_version = NULL, units = NULL, sc = sc_default()) {
  sc_call("import_segmentation", format = format, paths = .sc_array(paths), cell_column = cell_column, cell_property = cell_property, cells = cells, citation = citation, coordinate_system = coordinate_system, dataset = dataset, points = points, table = table, tool = tool, tool_version = tool_version, units = units, sc = sc)
}

#' Compare two segmentations
#'
#' Compares two segmentations of a dataset (by name or artifact id; A the default segmentation
#' and B the latest other if not given), as a job, in the Segmentation view: which cells
#' correspond (a shared nucleus, or half of one within the other), each difference's class
#' (one-to-one, expanded, contracted, split, merged, rearranged, only in A or B,
#' assignment-only), each segmentation's cells, nuclei, assigned fraction, transcripts per
#' cell, areas, spurious co-expression (Jones et al. 2025) and mutually exclusive co-expression
#' (Hartman and Satija 2024), and between them the pixels that agree, the transcripts whose
#' cell changed, the IoU and the boundary displacement. Recorded as a comparison artifact;
#' asking again answers it.
#'
#' @param a Segmentation A, by name or artifact id. Optional; a string.
#' @param b Segmentation B, by name or artifact id. Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_compare_segmentations <- function(a = NULL, b = NULL, dataset = NULL, sc = sc_default()) {
  sc_call("compare_segmentations", a = a, b = b, dataset = dataset, sc = sc)
}

#' Cluster the cells
#'
#' Clusters a segmentation's cells by their gene expression, as a job, in the Cell types view:
#' the cells with at least a number of gene transcripts of quality 20 or more (or those a QC
#' filter keeps), each cell's counts scaled to the median total and log-transformed, each gene
#' scaled (clipped at ±10), exact principal components, each cell's nearest neighbors weighted
#' as UMAP's graph, and Leiden communities at a resolution, seeded; each cluster's markers by
#' the Wilcoxon rank-sum test, exploratory. Recorded as a clustering artifact; asking again
#' answers it. Answers the clusters, their sizes and leading markers.
#'
#' @param components Principal components (50). Optional; a number.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param filter A QC filter choosing the cells (the instrument's segmentation only), by name
#' (its latest version), "name vN" or id. Optional; a string.
#' @param min_transcripts Without a filter, the cells analyzed have at least this many gene
#' transcripts (10). Optional; a number.
#' @param neighbors Each cell's neighborhood, the cell included (15). Optional; a number.
#' @param resolution Leiden's resolution: higher, more clusters (1). Optional; a number.
#' @param seed Leiden's seed (20250). Optional; a number.
#' @param segmentation The segmentation, by name or artifact id (the default if not given).
#' Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_cluster_cells <- function(components = NULL, dataset = NULL, filter = NULL, min_transcripts = NULL, neighbors = NULL, resolution = NULL, seed = NULL, segmentation = NULL, sc = sc_default()) {
  sc_call("cluster_cells", components = components, dataset = dataset, filter = filter, min_transcripts = min_transcripts, neighbors = neighbors, resolution = resolution, seed = seed, segmentation = segmentation, sc = sc)
}

#' Build a graph of the cells
#'
#' Builds a graph of which of a segmentation's cells are neighbors, as a job, in the Spatial
#' view: by the Delaunay triangulation of their centroids (its edges up to a longest length),
#' each cell's k nearest (an edge when either is among the other's k), a radius, or contact in
#' the segmentation's label raster (cells touching, or within a gap, with the boundary they
#' share). Built over all the cells, a QC filter's or those in regions, never cells a review
#' excluded. Recorded as a graph artifact; asking again answers it. Answers the cells and
#' edges, the neighbors a cell, the cells without one, the pieces and the edges' lengths.
#'
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param filter A QC filter choosing the cells (the instrument's segmentation only), by name
#' (its latest version), "name vN" or id. Optional; a string.
#' @param gap A contact graph's gap closed, µm (0: touching). Optional; a number.
#' @param k A k-nearest graph's neighbors of each cell (6). Optional; a number.
#' @param kind delaunay (the default), knn, radius or contact. Optional; a string.
#' @param longest A Delaunay graph's longest edge, µm (50; 0 keeps every edge). Optional; a
#' number.
#' @param radius A radius graph's distance, µm (20). Optional; a number.
#' @param regions Only the cells in these regions, by name or ID. Optional; a vector of strings
#' (Python: a list).
#' @param segmentation The segmentation, by name or artifact id (the default if not given).
#' Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_build_graph <- function(dataset = NULL, filter = NULL, gap = NULL, k = NULL, kind = NULL, longest = NULL, radius = NULL, regions = NULL, segmentation = NULL, sc = sc_default()) {
  sc_call("build_graph", dataset = dataset, filter = filter, gap = gap, k = k, kind = kind, longest = longest, radius = radius, regions = .sc_array(regions), segmentation = segmentation, sc = sc)
}

#' Ask how the cells are arranged
#'
#' Asks a question of a label set's cells, as a job, in the Spatial view. Neighborhood
#' enrichment: for each pair of labels, the neighbors between their cells in a graph against
#' the number expected if the labels were dealt to the same cells at random (exactly), as a
#' ratio, with a z-score and two-sided p-value from seeded permutations of the labels (within
#' regions, optionally, keeping each one's composition), Benjamini–Hochberg adjusted.
#' Co-occurrence: at each distance, how much likelier each label's cells are within it (or
#' since the distance before) of another label's than of any cell. Nearest distances: each
#' label's cells' distance to the nearest of each label, its median against the labels dealt at
#' random (z, p), and its distribution with an envelope. Ripley's K and L: of each label and
#' across each pair, in a window (the tissue or a region), with Ripley's isotropic edge
#' correction, against the envelope of the labels dealt at random, with a global test. Regions
#' compared: each region's cells by label per mm² of the tissue within it (a density, Garwood's
#' interval) and per labeled cell (a share, Wilson's), the tissue in none of them a row of its
#' own; each region over it as ratios (exact conditional and Koopman's intervals). Across a
#' region's edge: each label's density in bands of signed distance from the edge (inside
#' negative), each band's own tissue its denominator; the core, the margin and around compared,
#' saying which labels fill the region, stay out or gather at its margin. Niches (cellular
#' neighborhoods): each cell's neighborhood (its nearest labeled cells, or those within a
#' radius) by its labels' shares, the cells grouped by k-means with k-means++ seeding into
#' niches, each with its make-up against the tissue's, its defining labels and leading genes,
#' and the niches from further seeds compared by the adjusted Rand index; the niches are a
#' label set too (fill labels:<their id>:0, or niches). Spatially variable genes (moran, of
#' genes, no labels): each gene's Moran's I over a graph, its variances under normality and
#' randomization, the analytic test and permutations, Benjamini–Hochberg over the genes; the
#' leading genes' local Moran's I (each cell high among high, low among low, or unlike its
#' neighbors). A section's cells are not replicates: these describe this section. Recorded as
#' an analysis artifact; asking again answers it. Answers the pairs, the ratios at each
#' distance, the curves, the regions' table, the bands and readings, the niches, or the genes
#' ranked by Moran's I.
#'
#' @param closing Ripley's K in the tissue, regions compared, across an edge: gaps between
#' cells narrower than twice this are tissue, µm (10). Optional; a number.
#' @param correction Ripley's K: the edge correction, isotropic (the default) or none.
#' Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param every The step between distances, µm: co-occurrence 10, Ripley's K 5, nearest
#' distances' distribution 2.5, the bands across an edge 10. Optional; a number.
#' @param filter All but enrichment: a QC filter choosing the cells (the instrument's
#' segmentation only). Optional; a string.
#' @param graph Enrichment, Moran's I: a graph of the segmentation, by id (the latest built if
#' not given). Optional; a string.
#' @param labels A label set of the segmentation, by id (the latest if not given); niches too,
#' by their analysis's id. Optional; a string.
#' @param level The label set's level, by number from 1 or name. Optional; a string.
#' @param local Moran's I: the leading genes whose local Moran's I is kept (10). Optional; a
#' number.
#' @param local_permutations Moran's I: each cell's conditional permutations for its local
#' Moran's I (199). Optional; a number.
#' @param margin Across an edge: the margin's half-width, µm (20): the core is inside beyond
#' it, around is outside beyond it. Optional; a number.
#' @param neighbors Niches: each cell's neighborhood, its nearest labeled cells (10). Optional;
#' a number.
#' @param niches Niches: how many (6). Optional; a number.
#' @param pairs Co-occurrence: within (each distance, as Squidpy; the default) or between
#' (since the distance before). Optional; a string.
#' @param permutations How many times the labels are dealt again: enrichment 1,000; nearest
#' distances and Ripley's K 199. Moran's I: the cells' values dealt again, 199 (0: the analytic
#' test). Optional; a number.
#' @param question enrichment (the default), cooccurrence, distances, ripley, regions,
#' boundary, niches or moran. Optional; a string.
#' @param radius Niches: each cell's neighborhood, the labeled cells within this, µm (instead
#' of the nearest). Optional; a number.
#' @param reach Nearest distances: the farthest searched, µm (100); a cell with none nearer
#' counts at it. Across an edge: how far the bands reach either side, µm (100). Optional; a
#' number.
#' @param region Across an edge: the region whose edge to cross, by name or ID. Optional; a
#' string.
#' @param regions Regions compared: the regions to compare (names or IDs, up to 20).
#' Co-occurrence, nearest distances, Ripley's K: only the cells in these regions. Optional; a
#' vector of strings (Python: a list).
#' @param seed The permutations' seed (20250). Optional; a number.
#' @param seeds Niches: further seeds whose niches are compared with these (4). Optional; a
#' number.
#' @param segmentation The segmentation, by name or artifact id (the default if not given).
#' Optional; a string.
#' @param starts Niches: k-means's starts, the best kept (10). Optional; a number.
#' @param up_to Co-occurrence: the farthest distance, µm (150); Ripley's K: the farthest radius
#' (100). Optional; a number.
#' @param weight Enrichment: edges (the default) or boundary (a contact graph's shared
#' boundary). Optional; a string.
#' @param weights Moran's I: row (standardized, the default) or binary. Optional; a string.
#' @param window Ripley's K: the window, tissue (the default: the cells' footprint, its gaps
#' closed) or a region by name or ID. Optional; a string.
#' @param within Enrichment: deal the labels within each of these regions (names or IDs).
#' Optional; a vector of strings (Python: a list).
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_spatial_analysis <- function(closing = NULL, correction = NULL, dataset = NULL, every = NULL, filter = NULL, graph = NULL, labels = NULL, level = NULL, local = NULL, local_permutations = NULL, margin = NULL, neighbors = NULL, niches = NULL, pairs = NULL, permutations = NULL, question = NULL, radius = NULL, reach = NULL, region = NULL, regions = NULL, seed = NULL, seeds = NULL, segmentation = NULL, starts = NULL, up_to = NULL, weight = NULL, weights = NULL, window = NULL, within = NULL, sc = sc_default()) {
  sc_call("spatial_analysis", closing = closing, correction = correction, dataset = dataset, every = every, filter = filter, graph = graph, labels = labels, level = level, local = local, local_permutations = local_permutations, margin = margin, neighbors = neighbors, niches = niches, pairs = pairs, permutations = permutations, question = question, radius = radius, reach = reach, region = region, regions = .sc_array(regions), seed = seed, seeds = seeds, segmentation = segmentation, starts = starts, up_to = up_to, weight = weight, weights = weights, window = window, within = .sc_array(within), sc = sc)
}

#' Make an analysis again on another segmentation
#'
#' Makes a spatial analysis again on another segmentation of its dataset, in one step, in the
#' Spatial view: the two segmentations compared (unless they are), its labels made again from
#' the same clustering parameters and marker set (or reference), its graph built again with the
#' same definition over the same regions' cells, and the question asked with the same
#' parameters, regions and window. The new analysis is recorded as made from the first. Answers
#' the two read together: each number under both (keyed by label and gene names), the change,
#' the numbers' rank correlation, and the largest changes. Labels imported, curated or in a
#' consensus, and niches, are not made again.
#'
#' @param segmentation The other segmentation, by name or artifact id. Required; a string.
#' @param analysis The analysis, by id (the latest if not given). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_remake_analysis <- function(segmentation, analysis = NULL, dataset = NULL, sc = sc_default()) {
  sc_call("remake_analysis", segmentation = segmentation, analysis = analysis, dataset = dataset, sc = sc)
}

#' Show the map
#'
#' Shows a clustering in the Cell types view, with its map (UMAP; made first if it has none)
#' beside the tissue, linked: the cells colored by a clustering's clusters, a gene's
#' expression, their gene transcripts, area or how faithfully the map keeps their neighbors,
#' and a selection of cells (by cluster, or inside a polygon on the map or the tissue) drawn on
#' both. Answers the map's trustworthiness, the selection's size and its composition by
#' cluster.
#'
#' @param clustering A clustering, by artifact id or name; SituCraft's latest if not given.
#' Optional; a string.
#' @param color_by clusters (the clustering's), clusters:<clustering>, labels (its latest label
#' set, the first level), labels:<level>, labels:<label set>:<level>, confidence, a gene's
#' name, transcripts, area or reliability. Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param map The map: a map's artifact id, or instrument for the instrument's; the
#' clustering's own if not given. Optional; a string.
#' @param picture Answer a picture of the map too, by its clusters or a label set (a PNG): an
#' agent gets it as an image. Optional; TRUE or FALSE (Python: True or False).
#' @param picture_width The picture's width in pixels (1,000; 300 to 2,000). Optional; a
#' number.
#' @param select {"clusters": [numbers from 1]}, {"polygon": [[x, y], …], "on": "map" or
#' "tissue" (µm)}, or "none". Optional; any value.
#' @param file Optional; ask for the picture and save it to this path (the tissue a JPEG, a map or a figure a PNG).
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_show_map <- function(clustering = NULL, color_by = NULL, dataset = NULL, map = NULL, picture = NULL, picture_width = NULL, select = NULL, file = NULL, sc = sc_default()) {
  if (!is.null(file) && is.null(picture)) picture <- TRUE
  result <- sc_call("show_map", clustering = clustering, color_by = color_by, dataset = dataset, map = map, picture = picture, picture_width = picture_width, select = select, sc = sc)
  if (!is.null(file)) sc_save_image(result, file)
  result
}

#' Name clusters
