#' removes one.
#'
#' @param names By cluster number from 1: {"1": "T cells", "4": "Fibroblasts"}. Required; a
#' named list (Python: a dict).
#' @param clustering A clustering, by artifact id or name; SituCraft's latest if not given.
#' Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_name_clusters <- function(names, clustering = NULL, dataset = NULL, sc = sc_default()) {
  sc_call("name_clusters", names = names, clustering = clustering, dataset = dataset, sc = sc)
}

#' Add the instrument's clusters
#'
#' Adds one of the instrument's own clusterings (analysis.tar.gz: graph-based, or k-means of 2
#' to 10 clusters) to the project as a clustering of its segmentation, its markers computed by
#' SituCraft, and the instrument's map with it the first time.
#'
#' @param clustering graph-based (the default), k-means N, or its folder's name
#' (gene_expression_kmeans_5_clusters). Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_instrument_clusters <- function(clustering = NULL, dataset = NULL, sc = sc_default()) {
  sc_call("instrument_clusters", clustering = clustering, dataset = dataset, sc = sc)
}

#' Label the cells from markers
#'
#' Labels a clustering's cells from a marker set, as a job, in the Cell types view: each cell
#' scored for each label by its markers' expression against control genes binned by mean
#' expression (Tirosh et al. 2016, as scanpy's score_genes), a label's negative markers
#' counting against it where expressed; labels assigned from the top of the hierarchy down, a
#' level only when its best label leads the next by the margin. The marker set: one of the
#' project's (by name or id, its latest version), one SituCraft ships (breast, lung, or
#' simulated for a simulated tissue; the first that fits the panel if none is given), or a set
#' given in full (saved in the project). Recorded as a labels artifact; asking again answers
#' it. Answers the cells labeled at each level, each label's cells and markers, and each
#' cluster's leading labels.
#'
#' @param bins Expression bins (25). Optional; a number.
#' @param clustering A clustering, by artifact id or name; SituCraft's latest if not given.
#' Optional; a string.
#' @param controls Control genes per bin (50). Optional; a number.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param lineage Leave each label's lineage's markers out of its controls (true). Optional;
#' TRUE or FALSE (Python: True or False).
#' @param margin How far a level's best label must lead the next (0.1). Optional; a number.
#' @param markers A marker set: the project's by name or id, or SituCraft's breast, lung or
#' simulated. Optional; a string.
#' @param minimum The score a label must reach (0). Optional; a number.
#' @param name_clusters Name the clusters by their labels: true, or the share of a cluster's
#' cells its label must hold (0.3 to 1; 0.5 for true). Optional; any value.
#' @param seed The draws of control genes (20250). Optional; a number.
#' @param set A marker set in full (docs/FORMATS.md): {"format": "situcraft-markers",
#' "version": 1, "name", "levels", "labels": [{"name", "parent", "positive", "negative"}],
#' "states"}. Optional; a named list (Python: a dict).
#' @param state The score a state's markers must reach (0.25). Optional; a number.
#' @param sc A connection from sc_connect() (default: the last one made).
#' @return A situcraft_result: the message and the data SituCraft answered with.
#' @export
sc_label_cells <- function(bins = NULL, clustering = NULL, controls = NULL, dataset = NULL, lineage = NULL, margin = NULL, markers = NULL, minimum = NULL, name_clusters = NULL, seed = NULL, set = NULL, state = NULL, sc = sc_default()) {
  sc_call("label_cells", bins = bins, clustering = clustering, controls = controls, dataset = dataset, lineage = lineage, margin = margin, markers = markers, minimum = minimum, name_clusters = name_clusters, seed = seed, set = set, state = state, sc = sc)
}

#' Label the cells from a reference
#'
#' Labels a clustering's cells from a labeled single-cell reference, as a job, in the Cell
#' types view: an AnnData object in Zarr (a folder or a zip; its cells' labels in an obs
#' column, its counts or log-normalized values in X, raw/X or a layer), or a table of each
#' label's mean expression (CSV, TSV or Parquet; a row per label or per gene). The reference is
#' restricted to the panel's genes; each label's profile is its cells' mean log-normalized
#' expression; each cell is correlated (Spearman) with each label's profile over the genes most
#' higher in one label than another, then again on the leading labels' own genes until one is
#' left (Aran et al. 2019), and takes the last round's best when it leads the next by the
#' margin. An .h5ad file is read once written as Zarr (anndata's write_zarr). The columns are
#' found by their usual names unless given. Recorded as a labels artifact; asking again answers
#' it. Answers the genes shared, the cells labeled, each label's cells and each cluster's
#' leading labels.
#'
#' @param clustering A clustering, by artifact id or name; SituCraft's latest if not given.
#' Optional; a string.
#' @param dataset A dataset of the project by name or id; the one in focus, else the first, if
#' not given. Optional; a string.
#' @param gene_column The var column of gene names (the index if not given; or, for a table of
#' a row per gene, its genes' column). Optional; a string.
#' @param label_column The obs column of the reference cells' labels (or, for a table of a row
#' per label, its labels' column). Optional; a string.
#' @param margin How far the best label must lead the next, in correlation (0). Optional; a
#' number.
#' @param markers Genes per pair of labels (0: 500 × (2/3)^log₂(labels)). Optional; a number.
#' @param matrix The AnnData object's matrix: X, raw/X or layers/<name> (counts preferred;
#' found if not given). Optional; a string.
